 series.forEach((s,si)=>{let chunks=[],chunk=[];s.values.forEach((v,i)=>{if(v==null||!Number.isFinite(v)){if(chunk.length)chunks.push(chunk);chunk=[];}else chunk.push([x(i),y(v)]);});if(chunk.length)chunks.push(chunk);chunks.forEach(c=>{const points=c.map(p=>p.join(',')).join(' ');if(series.length<=2&&c.length>1)svg+='<polygon points="'+c[0][0]+','+base+' '+points+' '+c.at(-1)[0]+','+base+'" fill="url(#'+id+'-'+si+')"/>';svg+='<polyline class="chart-line" fill="none" stroke="'+s.color+'" stroke-width="'+(series.length>2?2.3:2.8)+'" stroke-linejoin="round" stroke-linecap="round" points="'+points+'"/>';});s.values.forEach((v,i)=>{if(v==null||!Number.isFinite(v))return;const tip=esc(s.name+' · '+labels[i]+'：'+num(v,Number.isInteger(v)?0:1));svg+='<circle class="point" '+(clicks?'data-month-index="'+i+'" tabindex="0" role="button" aria-label="查看'+(i+1)+'月"':'')+' cx="'+x(i)+'" cy="'+y(v)+'" r="'+(labels.length<=12?4:2.8)+'" fill="'+s.color+'" stroke="#0b1c30" stroke-width="2"><title>'+tip+'</title></circle>';});});
