function cohort(){return D.cohorts.find(c=>c.platform===state.product&&c.current===state.month);}
function retention(){const c=cohort();if(!c)return empty('前月整月付費母體待補','此區以前月整月官儲會員追蹤本月進度；缺完整前月母體時不計流失人數。上方相同日數名單可獨立查看，兩者不互相替代。');const a=c.rows,none=a.filter(r=>r.currentCash===0),both=a.filter(r=>r.noRepurchase===true),returned=a.filter(r=>r.currentCash>0),shift=a.filter(r=>r.currentCash===0&&r.currentCoins>0);return`<div class="metrics">${metric('前月直接付費母體',a.length,'人',null,null,c.previous+' 整月')}${metric('本月仍直接儲值',returned.length,'人',null,null,'回購率 '+percent(returned.length/a.length))}${metric('本月未直接儲值',none.length,'人',null,null,'已排除當月直接回購')}${metric(c.merchantCovered?'兩類補入皆無':'幣商資料待補',c.merchantCovered?both.length:null,'人',null,null,c.merchantCovered?'未直儲且未向兩幣商收幣':'不能判為兩類皆無')}</div>`+panel('付費玩家去向','直接回購、改用幣商與未回購分開呈現',ring(c.merchantCovered?[{name:'本月直接回購',value:returned.length,color:'#d9ba75'},{name:'僅向幣商收幣',value:shift.length,color:'#82bfa9'},{name:'兩類補入皆無',value:both.length,color:'#6687a6'}]:[{name:'本月直接回購',value:returned.length,color:'#d9ba75'},{name:'未直接回購，幣商未知',value:none.length,color:'#6687a6'}]))+panel('逐人付費變化與未回購名單',`${c.previous} 整月 → ${c.current} 截至 ${c.cutoff} · 母體限定前月直接儲值會員`, `<div class="toolbar"><div class="group"><input id="playerSearch" aria-label="搜尋付費玩家" placeholder="搜尋 AID、暱稱" value="${esc(state.search)}"><select id="playerFilter" aria-label="付費玩家狀態"><option value="all">全部前月付費會員</option><option value="cash0">本月未直接儲值</option><option value="none">兩類補入皆無</option><option value="shift">未直儲但仍向幣商收幣</option><option value="down">本月直儲金額減少</option><option value="returned">本月有直接儲值</option></select></div><button id="exportPlayers">匯出目前名單 CSV</button></div><div id="playerRows"></div>`+sourceNote(c.merchantCovered?'後台逐月儲值排行＋9/1–10/19成功收贈禮，兩指定幣商：測試帳號03、測試帳號04。':'後台逐月儲值排行。此月幣商完整紀錄尚待補齊，幣商欄為未知。'))+`<div class="notice">未結月的金額差是「本月至今減前月整月」，用於追蹤進度，不代表完整月份衰退。${c.merchantCovered?'另有 '+shift.length+' 人未直儲但仍向幣商收幣。':'僅能確認停止直接儲值，不能推論停止所有補入。'} 未回購不等於未登入或已離開平台。</div>`;}
function filteredPlayers(){const c=cohort();if(!c)return[];const q=state.search.trim().toLowerCase();return c.rows.filter(r=>(!q||(r.aid+' '+r.name).toLowerCase().includes(q))&&({all:true,cash0:r.currentCash===0,none:r.noRepurchase===true,shift:r.currentCash===0&&r.currentCoins>0,down:r.currentCash<r.prevCash,returned:r.currentCash>0}[state.filter]??true)).sort((a,b)=>b.prevCash-a.prevCash);}
function paymentMonth(){return D.payments?.months.find(m=>m.platform===state.product&&m.month===state.month);}
function structure(){const p=paymentMonth();if(!p)return empty('此月份付費結構待完整排行','需完整後台期間儲值排行，才計算去重付費人數、客單與集中度。');const b=D.payments.bridges.find(b=>b.current===state.month&&(b.platform||'win')===state.product);const prev=D.payments.months.find(m=>m.month===prevMonth(state.month)&&(m.platform||'win')===state.product);const max=Math.max(1,...p.bands.map(x=>x.cash));return`<div class="metrics">${metric('直接付費人數',p.uniquePayers,'去重人',null,null,'儲值排行截至 '+p.cutoff)}${metric('ARPPU',p.arppu,'每位付費者儲值',null,null,'期間官儲 ÷ 去重付費會員')}${metric('前五大集中度',percent(p.top5Share),'占期間官儲')}${metric('前十大集中度',percent(p.top10Share),'占期間官儲')}</div>`+panel('付費金額分層','依本月期間儲值分類；不是會員歷史累計或當前VIP',bars(p.bands.map(r=>({name:r.name,before:prev?.bands.find(b=>b.name===r.name)?.cash??null,now:r.cash})),{left:'前月整月',right:'本月至 '+p.cutoff.slice(5)}))+ (b?panel('流失與補位：金額差從哪裡來','固定算式可核對；未結月為進度差，不能當作完整月衰退',`<div class="bridge">${[{name:'前月官儲',value:b.previousTotal,total:true},{name:'未續購者前月貢獻',value:-b.lostPreviousCash},{name:'續購者金額增減',value:b.retainedDelta},{name:'前月未付，本月付費',value:b.newOrReturningCash},{name:'本月官儲',value:b.currentTotal,total:true}].map(r=>`<div class="bridge-item"><div class="bridge-column ${r.total?'total':r.value<0?'negative':'positive'}" style="height:${Math.max(3,Math.abs(r.value)/Math.max(b.previousTotal,b.currentTotal)*155)}px"></div><strong class="${r.value<0?'down':''}">${r.value>0&&!r.total?'+':''}${num(r.value)}</strong><span>${esc(r.name)}</span></div>`).join('')}</div><p class="fine">前月官儲 − 未續購前月貢獻 ＋ 續購者增減 ＋ 前月未付者本月貢獻 ＝ 本月官儲。前月未付者可能是新客或回流，不能全算新註冊。</p>`):'')+panel('前五大玩家與集中度','以當期儲值排行排序；同一玩家的暱稱可能改變，以 AID 識別',table(['本月名次','AID / 暱稱','期間官儲','占比','前月金額','前月名次'],p.payers.slice(0,5).map((r,i)=>{const old=prev?.payers.find(x=>x.aid===r.aid);return row([i+1,`<span class="row-name">${esc(r.name)}</span><span class="sub aid">${esc(r.aid)}</span>`,num(r.cash),percent(r.cash/p.total),num(old?.cash),old?prev.payers.findIndex(x=>x.aid===r.aid)+1:'前月未付']);})))+sourceNote('後台儲值排行；期間 '+(Array.isArray(p.period)?p.period.join(' — '):p.cutoff));}
