function sources(){const names={win:'贏麻了',qz:'茄子',song:'爽爆',rd:'紅鑽',lucky:'來好運',bo:'來博',o8:'發又發',aos:'黑桃A',fcc:'財哥',cgb:'超吉爆'};return panel('買賣幣換算設定','依使用者指定；原始金幣保留，不套用活動與遊戲點數',table(['平台','買幣換算','賣幣換算'],Object.entries(coinPolicy().rates||{}).map(([key])=>row([esc(names[key]||key),coinRuleLabel(key,'buy'),coinRuleLabel(key,'sell')]))))+panel('後台來源與更新狀態','網站不保存後台帳密；缺少來源或驗證失敗時保留上次可用快照',table(['產品','每日資料起日','資料截至','來源','完整度'],D.platforms.map(p=>row([esc(p.name),esc(p.dailyFrom||'—'),esc(p.dailyThrough||'—'),p.dailyThrough?'後台直接產出':'待重新登入',p.dailyThrough?`${(D.daily[p.key]||[]).length} 個有記錄日`:'未接入']))))+panel('每日自動更新',D.update.schedule,`<div class="timeline"><div class="timeline-item"><time>08:00 · 原營運收集</time><p>原有流程從已登入後台取得資料。網站所有數字與計算只讀取後台原始資料；雲端表只參考分析架構，不補數字。</p></div><div class="timeline-item"><time>來源完整性檢查</time><p>核對執行日期、資料截止日、站點成功狀態與警告；缺少資料不填零。</p></div><div class="timeline-item"><time>更新與讀回驗證</time><p>${esc(D.update.mode)}。私人網站保存最新資料與每日版本，更新後讀回比對。</p></div></div><p class="fine">${esc(D.update.requirements)} 歷史渠道、逐人名單與活動明細各有自己的快照截止，必須另行補查，不能用首頁刷新時間冒充所有模組均已更新。</p>`)+panel('指標定義','保持跨頁面相同口徑',table(['項目','定義'],Object.entries(D.definitions).map(([k,v])=>row([esc({reportDeposit:'儲值',directDeposit:'直接儲值',merchant:'幣商收幣',churn:'截至目前未回購'}[k]||k),`<span style="white-space:normal;display:block;min-width:300px;text-align:left">${esc(v)}</span>`]))));}
function allView(){const data=D.platforms.map(p=>({p,...pair(p.key)})),ok=data.filter(x=>x.now),cash=ok.reduce((s,x)=>s+x.now.cash,0);return`<div class="metrics">${metric('已接入產品',ok.length,'/ 6 站')}${metric('可見產品直接儲值',cash,'現金',null,null,'依各站已取得日期，不是六站完整總額')}${metric('待補後台連線',6-ok.length,'站')}${metric('跨站去重玩家',null,'人',null,null,'尚無跨站身份對應')}</div><div class="coverage">${data.map(({p,now})=>`<article class="station"><strong>${esc(p.name)}</strong><p>${p.dailyThrough?'截至 '+p.dailyThrough:'等待後台登入'}</p><div class="metric-value small">${now?num(now.cash):'—'}</div><p>本月後台儲值 · 現金</p><button data-product-link="${p.key}">查看產品 →</button></article>`).join('')}</div>`+panel('產品對照','比較時保留來源日期；不同日期的產品不排高低名次',table(['產品','本月儲值','上月同期','同期幅度','日均活躍','付費率','範圍'],data.map(({p,now,before,comparable,day})=>row([esc(p.name),num(now?.cash),comparable?num(before?.cash):'—',comparable?trend(change(now.cash,before.cash)):'—',num(now?.dau,1),percent(now?.payRate),day?'1–'+day+'日':'待接入']))))+sourceNote('各站後台日報。六站總覽目前不把未知產品補零，也不跨站加總玩家人數。');}
function competitorView(c){return `<div class="notice">競品觀測僅涵蓋帳號可見的關鍵指標；會員個資與活動設置不可見。競品沒有資料的欄位，不可解讀為零。</div>`+(c.metrics?.length?panel('可見關鍵指標',c.period?.join(' — ')||'依後台查詢期間',table(['指標','數值','期間 / 口徑'],c.metrics.map(m=>row([esc(m.name),num(m.value),esc(m.period||m.note||'')])))):empty('競品後台連線與指標核對中','已納入觀測範圍，登入並確認報表口徑後呈現關鍵指標。'))+panel('可見範圍與來源','不推論無權限欄位',`<p class="fine">後台：${esc(c.url)}</p><p class="fine">${esc(typeof c.permissionScope==='object'?c.permissionScope.verified:c.permissionScope||'關鍵營運指標可見；會員個資與活動設置不可見。')}</p><p class="fine">${esc(c.status||'待連線')}</p>`);}
function csv(name,headers,rows){const safe=v=>{let s=String(v??'');if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const blob=new Blob(['\uFEFF'+[headers,...rows].map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
