function applyRefreshAccess(){const b=$('#refreshData');if(!b)return;const allowed=refreshAccess.canRefresh===true&&refreshAccess.readOnly===false;b.disabled=!allowed||refreshBusy;b.setAttribute('aria-disabled',String(b.disabled));b.title=allowed?'重新讀取後台':'瀏覽模式：可查閱報表與匯出資料，無法刷新後台數據。';if(!allowed)b.textContent='瀏覽模式 · 僅供查閱';else if(!refreshBusy)b.textContent='↻ 刷新數據';}
async function loadRefreshAccess(){const id=++refreshAccessRequest;refreshAccess={canRefresh:false,readOnly:true};applyRefreshAccess();let timer;try{const r=await Promise.race([fetch('/api/access',{cache:'no-store',credentials:'same-origin'}),new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('access_timeout')),5000);})]);if(!r.ok)throw Error('access_unavailable');const a=await r.json();if(id===refreshAccessRequest)refreshAccess=a?.canRefresh===true&&a?.readOnly===false?{canRefresh:true,readOnly:false}:{canRefresh:false,readOnly:true};}catch{if(id===refreshAccessRequest)refreshAccess={canRefresh:false,readOnly:true};}finally{clearTimeout(timer);if(id===refreshAccessRequest)applyRefreshAccess();}return refreshAccess;}
async function load(){void loadRefreshAccess();try{$('#reload').disabled=true;const res=await fetch('/api/data',{cache:'no-store'});if(!res.ok)throw Error('載入失敗 '+res.status);D=await res.json();if(typeof decodeDashboardTransport==='function')D=await decodeDashboardTransport(D);else if(typeof decodeDashboardPayload==='function')D=decodeDashboardPayload(D);if(D.schema!==1)throw Error('資料版本不相容');render();}catch(e){$('#content').innerHTML=empty('資料暫時無法載入',e.message+'，請重新整理或確認登入。');}finally{$('#reload').disabled=false;}}
function analysisPrompt(){return '你是營運分析師。請只根據附件的後台彙總資料，分析各站與前月同期的變化，依序說明官儲、買幣、賣幣、登入活躍、新舊會員、來源渠道、付費回購與集中度、活動與儲值包。每個結論附數值、期間與來源；區分已確認事實、相關性、待驗證因果與資料缺口。買賣幣只按附件coinConversion的使用者指定除數換算，保留原始金幣與公式；活動、遊戲與未設比率站點不得套用，營收依使用者指定公式官儲＋買幣換算－賣幣換算，缺任一必要數值不得計算，並非扣除活動及營運成本後淨利；缺值不是零；未結月不可當完整月；回流付費者不能全算新註冊。最後列3項優先查核與需要補的資料。不要捏造會員動機、活動成本或ROI。';}
function downloadAnalysisPack(){const pm=paymentMonth(),c=cohort(),p=pair();const pack={title:'營運分析資料包',generatedAt:D.generatedAt,platform:state.product,month:state.month,prompt:analysisPrompt(),definitions:D.definitions,coinConversion:coinPolicy(),fundingDaily:D.fundingDaily,currentPeriod:p.a.length?[p.a[0][0],p.a.at(-1)[0]]:null,comparison:{current:p.now,previous:p.comparable?p.before:null},monthly:D.monthly,monthSnapshots:D.monthSnapshots,channels:currentChannelPeriod()?.channels??null,paymentStructure:pm?{uniquePayers:pm.uniquePayers,total:pm.total,arppu:pm.arppu,top5Share:pm.top5Share,top10Share:pm.top10Share,bands:pm.bands}:null,bridge:D.payments?.bridges.find(b=>b.current===state.month&&(b.platform||'win')===state.product),funding:D.funding,cohortSummary:c?{previous:c.previous,current:c.current,cutoff:c.cutoff,priorPayers:c.rows.length,returned:c.rows.filter(r=>r.currentCash>0).length,noDirectDeposit:c.rows.filter(r=>r.currentCash===0).length,noRepurchase:c.merchantCovered?c.rows.filter(r=>r.noRepurchase===true).length:null}:null,competitors:D.competitors.map(c=>({name:c.name,metrics:c.normalizedMetrics,monthly:c.normalizedMonthly,notes:c.dataNotes})),privacy:'此資料包不含逐人AID、暱稱、電話或登入帳密。'};const blob=new Blob([JSON.stringify(pack,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='營運分析-'+state.product+'-'+state.month+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let refreshTimer=null;
function showRefresh(job){const el=$('#refreshStatus');if(!job||job.state==='idle'){el.hidden=true;return;}el.hidden=false;const labels={queued:'排隊中',running:'正在讀取後台',succeeded:'數據已更新',partial:'部分站點已更新',failed:'更新失敗'};el.className='refresh-status'+(job.state==='failed'?' error':'');el.textContent=(labels[job.state]||job.state)+' · '+(job.summary||'')+(job.finishedAt?' · '+new Date(job.finishedAt).toLocaleTimeString('zh-TW',{timeZone:'Asia/Taipei',hour12:false}):'');refreshBusy=['queued','running'].includes(job.state);$('#refreshData').disabled=refreshBusy||!refreshAccess.canRefresh;$('#refreshData').textContent=job.state==='running'?'◌ 讀取後台中':job.state==='queued'?'◌ 等待收集器':'↻ 刷新數據';applyRefreshAccess();}
async function requestRefresh(){if(!refreshAccess.canRefresh||refreshAccess.readOnly){applyRefreshAccess();return;}try{$('#refreshData').disabled=true;const r=await fetch('/api/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error('無法提出刷新要求（'+r.status+'）');const job=await r.json();showRefresh(job);watchRefresh(job.id);}catch(e){showRefresh({state:'failed',summary:e.message+'；保留上次有效數據。'});}}
function watchRefresh(id){if(refreshTimer)clearInterval(refreshTimer);let polls=0;refreshTimer=setInterval(async()=>{try{const r=await fetch('/api/refresh',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);const job=await r.json();showRefresh(job);if(!['queued','running'].includes(job.state)){clearInterval(refreshTimer);refreshTimer=null;if(['succeeded','partial'].includes(job.state))await load();}else if(++polls>300){clearInterval(refreshTimer);refreshTimer=null;refreshBusy=false;applyRefreshAccess();$('#refreshStatus').textContent='等待收集器回應。請確認收集電腦開機且登入有效；上次數據仍可查看。';}}catch{clearInterval(refreshTimer);refreshTimer=null;refreshBusy=false;applyRefreshAccess();$('#refreshStatus').textContent='暫時無法取得刷新進度；上次有效數據保留。';}},2000);}
$('#year').onchange=e=>{state.year=Number(e.target.value);state.month=state.year+state.month.slice(4);state.page=1;state.channel='';state.search='';state.filter='all';render()};$('#month').onchange=e=>{state.month=e.target.value;state.page=1;state.channel='';state.search='';state.filter='all';render()};$('#reload').onclick=load;$('#refreshData').onclick=requestRefresh;$('#closeDetail').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};load();
